alter table public.schoolpro_custom_requests add column if not exists currency text not null default 'NGN',add column if not exists quote_expires_at timestamptz,add column if not exists quote_accepted_at timestamptz,add column if not exists invoice_reference text,add column if not exists payment_status text not null default 'unpaid',add column if not exists provisioning_notes text;
create table if not exists public.schoolpro_site_settings(school_id uuid primary key references public.schoolpro_schools(id) on delete cascade,site_slug text unique,custom_domain text unique,logo_url text,school_email text,phone text,address text,motto text,primary_color text default '#6d28d9',secondary_color text default '#0f172a',hero_title text,hero_text text,admissions_open boolean not null default false,result_checker_enabled boolean not null default true,portal_enabled boolean not null default true,is_published boolean not null default false,updated_at timestamptz not null default now());
create table if not exists public.schoolpro_admission_acceptances(id uuid primary key default gen_random_uuid(),application_id uuid not null unique references public.schoolpro_admissions(id) on delete cascade,accepted_by_name text not null,accepted_by_email text,accepted_at timestamptz not null default now(),terms_accepted boolean not null default true,notes text);
create table if not exists public.schoolpro_portal_invites(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schoolpro_schools(id) on delete cascade,student_id uuid references public.schoolpro_students(id) on delete cascade,email text not null,invite_type text not null check(invite_type in('student','parent')),token uuid not null default gen_random_uuid(),status text not null default 'pending',expires_at timestamptz not null default(now()+interval '7 days'),accepted_at timestamptz,created_at timestamptz not null default now(),unique(token));
alter table public.schoolpro_site_settings enable row level security;alter table public.schoolpro_admission_acceptances enable row level security;alter table public.schoolpro_portal_invites enable row level security;
grant select on public.schoolpro_site_settings to anon,authenticated;grant insert,update,delete on public.schoolpro_site_settings to authenticated;grant select,insert on public.schoolpro_admission_acceptances to anon,authenticated;grant select,insert,update on public.schoolpro_portal_invites to authenticated;
create policy "published school sites public" on public.schoolpro_site_settings for select to anon,authenticated using(is_published=true or exists(select 1 from public.schoolpro_members m where m.school_id=schoolpro_site_settings.school_id and m.user_id=(select auth.uid())));
create policy "school site managers write" on public.schoolpro_site_settings for all to authenticated using(exists(select 1 from public.schoolpro_members m where m.school_id=schoolpro_site_settings.school_id and m.user_id=(select auth.uid()) and m.role::text in('proprietor','administrator','it_admin'))) with check(exists(select 1 from public.schoolpro_members m where m.school_id=schoolpro_site_settings.school_id and m.user_id=(select auth.uid()) and m.role::text in('proprietor','administrator','it_admin')));
